// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Montserrat');

const { fontFamily } = loadFont();



export type CountdownProps = Record<string, any>;

const Countdown: React.FC<CountdownProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 10,
  textColor = "#ffffff",
  floatingSymbolColor = "#10b981",
  startValue = 0,
  endValue = 2500000,
  floatingSymbolCount = 50,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const totalFrames = fps * durationInSeconds;

  // Calculate current countdown value
  const currentValue = Math.round(
    interpolate(frame, [0, totalFrames], [startValue, endValue], {
      extrapolateRight: "clamp",
    })
  );

  const formattedValue = `$${currentValue.toLocaleString("en-US")}`;

  // Generate deterministic random properties for floating symbols
  const symbols = useMemo(() => {
    return new Array(floatingSymbolCount).fill(0).map((_, i) => {
      return {
        id: i,
        // Distribute starting X positions across the screen
        xStart: random(`x-${i}`) * width,
        // Start below the screen
        yStart: height + random(`y-${i}`) * height * 0.5,
        // End above the screen
        yEnd: -height * 0.5 - random(`yEnd-${i}`) * height,
        // Varying speeds
        speed: 0.3 + random(`speed-${i}`) * 1.5,
        // Varying sizes
        scale: 0.3 + random(`scale-${i}`) * 2.5,
        // Subtle opacities so they don't overpower the main text
        opacity: 0.05 + random(`opacity-${i}`) * 0.25,
        // Phase for horizontal sway
        phase: random(`phase-${i}`) * Math.PI * 2,
      };
    });
  }, [floatingSymbolCount, width, height]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        overflow: "hidden",
      }}
    >
      {/* Background Floating Symbols */}
      {symbols.map((sym) => {
        // Calculate vertical position based on frame and speed
        const yPos = interpolate(
          frame * sym.speed,
          [0, totalFrames],
          [sym.yStart, sym.yEnd],
          { extrapolateRight: "clamp" }
        );

        // Calculate gentle horizontal sway
        const sway = Math.sin(frame * 0.02 + sym.phase) * 80 * sym.scale;
        const xPos = sym.xStart + sway;

        return (
          <div
            key={sym.id}
            style={{
              position: "absolute",
              left: xPos,
              top: yPos,
              fontSize: 100 * sym.scale,
              fontWeight: 900,
              color: floatingSymbolColor,
              opacity: sym.opacity,
              transition: "none",
              userSelect: "none",
            }}
          >
            $
          </div>
        );
      })}

      {/* Main Countdown Text */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div
          style={{
            fontSize: Math.min(width, height) * 0.15,
            fontWeight: 900,
            color: textColor,
            textAlign: "center",
            transition: "none",
            // Subtle shadow to separate from background elements
            textShadow: `0px 10px 40px rgba(0,0,0,0.5)`,
            letterSpacing: "-0.02em",
          }}
        >
          {formattedValue}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default Countdown;